//js:
const qy71v = {
  host: 'https://www.71v.net',
  d: [],
  d_: [],
  categories: [
    { name: '首页', tid: 'home' },
    { name: '电影', tid: '1' },
    { name: '电视剧', tid: '2' },
    { name: '综艺', tid: '3' },
    { name: '动漫', tid: '4' },
    { name: '短剧', tid: '63' },
    { name: '体育', tid: '17' },
    { name: '纪录片', tid: '60' },
    { name: '游戏', tid: '21' },
    { name: '音乐', tid: '20' },
    { name: '预告片', tid: '11' },
    { name: '公益', tid: '23' },
  ],

  // ---- 工具 ----
  getDoc: function (html) {
    try {
      return PDFocument(html);
    } catch (e) {
      return null;
    }
  },

  // 从HTML中提取首个img[data-src]或src（upload域名图）
  pickImage: function (el) {
    if (!el) return '';
    try {
      var ds = el.attr('data-src') || el.attr('data-original') || el.attr('src') || '';
      if (ds && ds.indexOf('http') !== 0 && ds.indexOf('/') === 0) ds = this.host + ds;
      return ds;
    } catch (e) {
      return '';
    }
  },

  // 解析一条视频卡片（基于<a><img>结构，链接含/voddetail/）
  parseCard: function (aEl, titleEl, imgEl, descEl) {
    var self = this;
    var href = '';
    try { href = aEl ? (aEl.attr('href') || '') : ''; } catch (e) {}
    if (href && href.indexOf('http') !== 0 && href.indexOf('/') === 0) href = self.host + href;
    var title = '';
    try { title = titleEl ? (titleEl.text() || titleEl.attr('title') || '').trim() : ''; } catch (e) {}
    var img = imgEl ? self.pickImage(imgEl) : '';
    var desc = '';
    try { desc = descEl ? (descEl.text() || '').trim() : ''; } catch (e) {}
    // 从href提取vod_id /voddetail/ID/
    var vid = '';
    var m = href.match(/\/voddetail\/(\d+)/);
    if (m) vid = m[1];
    if (!title) return null;
    return {
      title: title,
      img: img,
      desc: desc,
      col_type: 'movie_3',
      url: $('hiker://empty').rule(function (o) {
        putMyVar('vod_id', o.vod_id);
        putMyVar('vod_name', o.vod_name);
        $.require('qy71v').detail();
      }, { vod_id: vid, vod_name: title }),
    };
  },

  // 从HTML中抽取视频卡片列表
  extractCards: function (html) {
    var self = this;
    var result = [];
    var doc = self.getDoc(html);
    if (!doc) return result;
    // MacCMS mx 主题常用：.module-items .module-item 或 .vodlist .vod-item 或 .stui-vodlist__item
    var selectors = [
      '.module-items .module-item',
      '.vodlist .vod-item',
      '.stui-vodlist__item',
      '.public-list-box .public-list-item',
      '.card',
    ];
    var items = null;
    for (var i = 0; i < selectors.length; i++) {
      try {
        var tmp = doc.querySelectorAll(selectors[i]);
        if (tmp && tmp.length >= 2) { items = tmp; break; }
      } catch (e) {}
    }
    if (!items || !items.length) {
      // 兜底：直接找a[href*=voddetail]
      try { items = doc.querySelectorAll('a[href*="/voddetail/"]'); } catch (e) {}
    }
    if (!items) return result;
    for (var j = 0; j < Math.min(items.length, 60); j++) {
      var it = items[j];
      var card = null;
      try {
        var a = it.tagName && it.tagName().toUpperCase() === 'A' ? it : (it.querySelector('a[href*="/voddetail/"]') || it.querySelector('a'));
        if (!a) continue;
        var img = it.querySelector('img') || (a && a.querySelector ? a.querySelector('img') : null);
        // 标题：a的text / a title / h3,h4
        var titleText = '';
        try { titleText = a.text() || ''; } catch (e) {}
        var titleNode = it.querySelector('h3, h4, .title, .vod_title, .module-item-title');
        if (titleNode) {
          try { titleText = titleNode.text() || titleText; } catch (e) {}
        }
        titleText = (titleText || '').trim();
        // 描述：.remarks / .subtitle / .vod_sub / .module-item-subtitle
        var descNode = it.querySelector('.remarks, .subtitle, .vod_sub, .module-item-subtitle, .module-item-content');
        var descText = '';
        if (descNode) { try { descText = descNode.text() || ''; } catch (e) {} }
        // 构造临时对象，然后复用parseCard
        var fakeA = { attr: function (n) { if (n === 'href') return a.attr ? a.attr('href') : ''; return ''; }, text: function () { return titleText; } };
        var fakeTitle = { text: function () { return titleText; }, attr: function () { return titleText; } };
        var fakeImg = img ? { attr: function (n) { return img.attr ? img.attr(n) : ''; } } : null;
        var fakeDesc = descText ? { text: function () { return descText; } } : null;
        card = self.parseCard(a, fakeTitle, fakeImg, fakeDesc);
      } catch (e) {}
      if (card) result.push(card);
    }
    return result;
  },

  // ---- 首页 ----
  home: function () {
    var self = this, d = this.d, d_ = this.d_;
    var pg = MY_PAGE || 1;
    if (pg == 1) {
      d_.push({ title: '搜索', col_type: 'input', extra: {
        onChange: $.toString(function (v) {
          putMyVar('keyword', v);
          $.require('qy71v').search();
        }),
      }});
      for (var i = 0; i < self.categories.length; i++) {
        (function (tn, tid) {
          d_.push({
            title: getMyVar('cat71', 'home') == tid ? '「' + tn + '」' : tn,
            url: $('#noLoading#').lazyRule(function (id) {
              putMyVar('cat71', id);
              refreshPage(false);
              return 'hiker://empty';
            }, tid),
            col_type: 'scroll_button',
          });
        })(self.categories[i].name, self.categories[i].tid);
      }
      setPreResult(d_);
    }
    var cat = getMyVar('cat71', 'home');
    if (cat === 'home') {
      self.homePage(pg);
    } else {
      self.category(cat, pg);
    }
    setResult(d);
  },

  // 首页抓取
  homePage: function (pg) {
    var self = this, d = this.d;
    var html;
    try {
      html = request(self.host + '/?pg=' + pg, { headers: { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 15_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15A148' } });
    } catch (e) {
      setError('首页请求失败：' + (e && e.message ? e.message : e));
      return;
    }
    var cards = self.extractCards(html);
    if (!cards.length) {
      d.push({ title: '首页未匹配到数据结构', col_type: 'text_center_1' });
    }
    for (var i = 0; i < cards.length; i++) d.push(cards[i]);
  },

  // 分类页：MacCMS 的 /vodtype/{tid}-----------/ 或 /vodshow/{tid}-----------.html
  category: function (tid, pg) {
    var self = this, d = this.d;
    var url = self.host + '/vodtype/' + tid + '-----------' + pg + '---.html';
    var html;
    try {
      html = request(url, { headers: { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 15_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15A148' } });
    } catch (e) {
      // fallback to vodshow
      try {
        url = self.host + '/vodshow/' + tid + '-----------' + pg + '---.html';
        html = request(url, { headers: { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 15_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15A148' } });
      } catch (e2) {
        setError('分类请求失败：' + (e2 && e2.message ? e2.message : e2));
        return;
      }
    }
    var cards = self.extractCards(html);
    if (!cards.length) {
      d.push({ title: '分类页无数据（可能被CF风控）', col_type: 'text_center_1' });
    }
    for (var i = 0; i < cards.length; i++) d.push(cards[i]);
  },

  // ---- 搜索 ----
  search: function () {
    var self = this, d = this.d;
    var kw = getMyVar('keyword', '');
    if (!kw) { setResult(d); return; }
    var pg = MY_PAGE || 1;
    var url = self.host + '/vodsearch/-------------' + pg + '---/?wd=' + encodeURIComponent(kw);
    var html;
    try {
      html = request(url, { headers: { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 15_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15A148' } });
    } catch (e) {
      setError('搜索失败：' + (e && e.message ? e.message : e));
      return;
    }
    var cards = self.extractCards(html);
    if (!cards.length) {
      d.push({ title: '没有找到“' + kw + '”相关的影片', col_type: 'text_center_1' });
    }
    for (var i = 0; i < cards.length; i++) d.push(cards[i]);
    setResult(d);
  },

  // ---- 详情：从 voddetail/ID 页面解析 影片信息 + 线路+剧集 ----
  detail: function () {
    var self = this, d = this.d;
    var vid = MY_PARAMS.vod_id || getMyVar('vod_id', '');
    var name = MY_PARAMS.vod_name || getMyVar('vod_name', '');
    setPageTitle(name || '详情');
    if (!vid) { setError('缺少vod_id'); setResult(d); return; }
    var html;
    try {
      html = request(self.host + '/voddetail/' + vid + '/', { headers: { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 15_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15A148' } });
    } catch (e) {
      setError('详情请求失败：' + (e && e.message ? e.message : e));
      return;
    }
    var doc = self.getDoc(html);
    if (!doc) { setError('详情HTML解析失败'); setResult(d); return; }

    // 1. 影片元数据（兜底：标题/封面/信息区 class="vod-info", ".module-info", ".stui-content__detail"）
    var vTitle = '';
    try { vTitle = (doc.querySelector('h1') || doc.querySelector('h2') || doc.querySelector('.vod_title, .module-info-title, .title')).text().trim(); } catch (e) {}
    if (!vTitle) vTitle = name || '';
    var vPic = '';
    try {
      var img = doc.querySelector('.vod-img img, .module-info-poster img, .stui-content__thumb img, img[src*="/upload/"]');
      vPic = self.pickImage(img);
    } catch (e) {}
    var infoText = '';
    try {
      var info = doc.querySelector('.vod_content, .vod-data, .module-info-content, .stui-content__detail, .vod-info');
      infoText = info ? (info.text() || '').replace(/\s+/g, ' ').trim() : '';
    } catch (e) {}
    var introText = '';
    try {
      var intro = doc.querySelector('.vod_content_intro, .module-info-intro, .detail-content, .vod_content, .stui-content__detail .detail-sketch');
      introText = intro ? (intro.text() || '').trim() : '';
    } catch (e) {}

    d.push({
      title: vTitle || name || '',
      desc: infoText || '',
      img: vPic,
      url: vPic ? (vPic + '#.jpg#') : '',
      col_type: 'movie_1_vertical_pic_blur',
    });
    if (introText) {
      d.push({
        title: '<b><font color="#098AC1">∷剧情简介</font></b><br>' + introText,
        col_type: 'rich_text',
        extra: { lineSpacing: 6, textSize: 15, lineVisible: true },
      });
    }

    // 2. 线路（播放源）+ 剧集：从 HTML 中解析 线路标签 + 每组 a[href^=/play/]
    var tabs = [];
    var lists = [];
    try {
      // 71v 永乐主题：.ylsp-pc-source-card / .ylsp-mobile-source-card 文本是 "自营1线"
      // 剧集：.ylsp-pc-episode-link / .ylsp-mobile-episode-option 等
      // 通用策略：抓取所有包含 "/play/" 的容器 -> 按最近的"线路组"分组
      // 简化方式：抓所有 a[href*=/play/]; 并 抓所有 线路容器（包含"线路/自营/全球/大陆"等关键字的标题文本）做分组
      var playAnchors = doc.querySelectorAll('a[href*="/play/"]');
      // 先分组：按 sid（/play/ID-sid-nid/）
      var groups = {};
      var order = [];
      if (playAnchors && playAnchors.length) {
        for (var k = 0; k < playAnchors.length; k++) {
          var a = playAnchors[k];
          var href = '';
          try { href = a.attr('href') || ''; } catch (e) {}
          var mm = href.match(/\/play\/(\d+)-(\d+)-(\d+)/);
          if (!mm) continue;
          var sid = mm[2];
          var nid = mm[3];
          var title = '';
          try { title = (a.text() || '').trim(); } catch (e) {}
          if (!title) continue;
          if (!groups[sid]) { groups[sid] = []; order.push(sid); }
          groups[sid].push({ t: title, nid: nid, href: href, vid: mm[1], sid: sid });
        }
      }
      // 线路名：从页面内抓文本包含"x线"的容器，或者简单用"线路1、线路2"
      var lineNames = {};
      var defaultLineIdx = 1;
      try {
        var lineNodes = doc.querySelectorAll('.ylsp-mobile-source-card, .ylsp-pc-source-card, a[href*="/play/"][href*="-1-1"], .module-player-handle-items [class*="source"], [class*="play-from"]');
        if (lineNodes && lineNodes.length) {
          for (var ln = 0; ln < lineNodes.length && ln < order.length; ln++) {
            var txt = '';
            try { txt = (lineNodes[ln].text() || '').replace(/\s+/g, '').trim(); } catch (e) {}
            // 过滤掉数字
            var pureName = txt.replace(/\d{2,}/g, '').replace(/个视频/g, '') || ('线路' + (ln + 1));
            lineNames[order[ln]] = pureName || ('线路' + (ln + 1));
          }
        }
      } catch (e) {}
      for (var oi = 0; oi < order.length; oi++) {
        var sidKey = order[oi];
        var arr = groups[sidKey];
        if (!arr || !arr.length) continue;
        var lname = lineNames[sidKey] || ('线路' + (defaultLineIdx++));
        tabs.push(lname + '(' + arr.length + ')');
        var eps = [];
        // 去重：保留第一个 nid
        var seen = {};
        for (var ai = 0; ai < arr.length; ai++) {
          if (seen[arr[ai].nid]) continue;
          seen[arr[ai].nid] = true;
          // 存：title$sid$nid$vid
          eps.push(arr[ai].t + '$' + arr[ai].sid + '$' + arr[ai].nid + '$' + arr[ai].vid);
        }
        if (eps.length) lists.push(eps);
      }
    } catch (e) {
      // ignore
    }

    if (lists.length) {
      d.push({ col_type: 'blank_block' });
      storage0.putMyVar('lists71', lists);
      var 排序 = getMyVar(MY_URL + '章节排序', '正序');
      var 提示 = 排序 == '倒序' ? '正序' : '倒序';
      d.push({
        title: 排序,
        url: $('#noLoading#').lazyRule(function (提示) {
          var ls = storage0.getMyVar('lists71');
          var cur = getMyVar(MY_URL, '0');
          var 新排序 = getMyVar(MY_URL + '章节排序', '正序') == '倒序' ? '正序' : '倒序';
          var 章节 = ls[cur] || [];
          if (新排序 == '倒序') 章节 = 章节.slice().reverse();
          var cp = [];
          for (var i = 0; i < 章节.length; i++) {
            var parts = 章节[i].split('$');
            cp.push({
              title: parts[0],
              url: $.require('qy71v').playUrl(parts[1], parts[2], parts[3]),
              col_type: 章节.length > 3 ? 'text_4' : 'text_2',
              extra: { cls: MY_URL + '_选集', id: parts[1] + '$' + parts[2] + '$' + parts[3] },
            });
          }
          deleteItemByCls(MY_URL + '_选集');
          addItemBefore(MY_URL + 'footer', cp);
          updateItem(MY_URL + '_排序', { title: 新排序 });
          putMyVar(MY_URL + '章节排序', 新排序);
          return 'hiker://empty';
        }),
        col_type: 'flex_button',
        extra: { id: MY_URL + '_排序' },
      });
      for (var ti = 0; ti < tabs.length; ti++) {
        (function (tname, tid) {
          d.push({
            title: getMyVar(MY_URL, '0') == String(tid) ? '「 ' + tname + '」' : tname,
            url: $('#noLoading#').lazyRule(function (tabs, id) {
              var ls = storage0.getMyVar('lists71');
              var 排序 = getMyVar(MY_URL + '章节排序', '正序');
              for (var x = 0; x < tabs.length; x++) {
                updateItem(MY_URL + '_线路' + x, { title: id == x ? '「' + tabs[x] + '」' : tabs[x] });
              }
              putMyVar(MY_URL, String(id));
              var 章节 = ls[getMyVar(MY_URL, '0')] || [];
              if (排序 == '倒序') 章节 = 章节.slice().reverse();
              var cp = [];
              for (var i = 0; i < 章节.length; i++) {
                var parts = 章节[i].split('$');
                cp.push({
                  title: parts[0],
                  url: $.require('qy71v').playUrl(parts[1], parts[2], parts[3]),
                  col_type: 章节.length > 3 ? 'text_4' : 'text_2',
                  extra: { cls: MY_URL + '_选集', id: parts[1] + '$' + parts[2] + '$' + parts[3] },
                });
              }
              deleteItemByCls(MY_URL + '_选集');
              addItemBefore(MY_URL + 'footer', cp);
              return 'hiker://empty';
            }, tabs, tid),
            col_type: 'flex_button',
            extra: { id: MY_URL + '_线路' + tid },
          });
        })(tabs[ti], ti);
      }
      var list = lists[getMyVar(MY_URL, '0')] || [];
      if (排序 == '倒序') list = list.slice().reverse();
      for (var gi = 0; gi < list.length; gi++) {
        var pp = list[gi].split('$');
        d.push({
          title: pp[0],
          url: $.require('qy71v').playUrl(pp[1], pp[2], pp[3]),
          col_type: list.length > 3 ? 'text_4' : 'text_2',
          extra: { cls: MY_URL + '_选集', id: pp[1] + '$' + pp[2] + '$' + pp[3] },
        });
      }
      d.push({ col_type: 'big_blank_block', extra: { id: MY_URL + 'footer' } });
    } else {
      d.push({ title: '未解析到播放剧集（详情页结构可能未匹配）', col_type: 'text_center_1' });
    }
    setResult(d);
  },

  playUrl: function (sid, nid, vid) {
    return $('').lazyRule(function (s, n, v) {
      return $.require('qy71v').play(s, n, v);
    }, sid, nid, vid);
  },

  // 播放：拉取 /play/VID-SID-NID/ 页面，抓 player_aaaa.url 作为真实播放地址
  play: function (sid, nid, vid) {
    var self = this;
    var url = self.host + '/play/' + vid + '-' + sid + '-' + nid + '/';
    var html;
    try {
      html = request(url, { headers: { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 15_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15A148' } });
    } catch (e) {
      setError('播放页请求失败：' + (e && e.message ? e.message : e));
      return 'hiker://empty';
    }
    var real = '';
    // 正则匹配：var player_aaaa={... "url":"真实地址" ...}
    try {
      var m = html.match(/var\s+player_aaaa\s*=\s*(\{[\s\S]*?\})\s*;/);
      if (m) {
        var obj = JSON.parse(m[1]);
        var rawUrl = obj && obj.url;
        if (rawUrl) {
          // 处理加密
          var enc = String(obj.encrypt || '0');
          if (enc === '1') {
            try { rawUrl = unescape(rawUrl); } catch (e) {}
          } else if (enc === '2') {
            try {
              if (typeof atob === 'function') rawUrl = unescape(atob(rawUrl));
            } catch (e) {}
          }
          real = rawUrl;
        }
      }
    } catch (e) {
      setError('解析player_aaaa失败：' + (e && e.message ? e.message : e));
      return 'hiker://empty';
    }
    if (!real) {
      // 兜底：匹配 any m3u8 or mp4 url in html
      try {
        var mm = html.match(/https?:\/\/[^"'s)]+\.(?:m3u8|mp4|flv)(?:\?[^"'s)]*)?/);
        if (mm) real = mm[0];
      } catch (e) {}
    }
    if (!real) {
      setError('播放地址为空（可能被CF风控或接口变了）');
      return 'hiker://empty';
    }
    return real;
  },
};
$.exports = qy71v;
